    },
    {
      "control_id": "CTRL-A-BIND-VALIDATION",
      "decision_effect": "Any future A canary must construct binds from structured allowlisted fields, reject traversal and out-of-workspace sources, and pass negative tests before eligibility.",
      "evidence": [
        "SEC-A-BIND"
      ],
      "owner": "Platform Security"
    },
    {
      "control_id": "CTRL-B-ISOLATION",
      "decision_effect": "B cutover requires executable admission tests showing workspace-only mounts and credentials scoped to the intended workspace; any failure invokes RT-B-ISOLATION.",
      "evidence": [
        "SEC-B-ISOLATION"
      ],
      "owner": "Platform Security"
    }
  ],
  "decision": {
    "conditional_optimization": {
      "eligible_only_if": [
        "A dated representative window shows a warm-dominant workload mix",
        "Separate warm-only reruns with disclosed execution identity confirm A's advantage over B without pooled inference",
        "An approved cold SLO and censoring rule exist and A passes a cold-only rerun",
        "CTRL-A-CLEANUP-AUTH and CTRL-A-BIND-VALIDATION pass with named owners",
        "A rollback rehearsal restores the preserved B state and its acceptance checks pass"
      ],
      "evidence": [
        "BM-A-WARM",
        "BM-B-WARM",
        "BM-D-WARM",
        "BM-A-COLD",
        "INC-A-CLEANUP",
        "SEC-A-BIND"
      ],
      "option": "A"
    },
    "depends_on": [
      "D-MIGRATION",
      "B-ISOLATION",
      "CON-MIGRATION",
      "CON-OWNER",
      "CON-ROLLBACK"
    ],
    "phases": [
      {
        "gates": [
          {
            "check": "Run a timed legacy-client migration rehearsal from preserved legacy state to D and record start time, end time, and compatibility results.",
            "expected": "D is active and all legacy acceptance checks pass within 14 calendar days of the decision.",
            "gate_id": "G-D-MIGRATION"
          },
          {
            "check": "Inspect the signed operations runbook and on-call roster before D activation.",
            "expected": "One specifically named cleanup owner and one specifically named recovery owner have acknowledged duties and escalation paths.",
            "gate_id": "G-OWNERS"
          },
          {
            "check": "From a D canary, execute rollback to the preserved legacy state and run legacy acceptance checks.",
            "expected": "The prior state is restored without data loss and all legacy checks pass inside the approved recovery-time objective.",
            "gate_id": "G-D-ROLLBACK"
          }
        ],
        "option": "D",
        "owner": "Execution Fabric Migration Team",
        "phase": 1,
        "purpose": "Provide the time-bounded legacy-compatible bridge asserted by PROP-D under CON-MIGRATION while recovery ownership from INC-D-RECOVERY remains gated.",
        "rollback_triggers": [
          {
            "action": "Stop D expansion and continue from the preserved legacy state while the migration plan is corrected.",
            "check": "Review the dated migration forecast daily and run legacy acceptance checks on every D canary.",
            "condition": "The forecast exceeds day 14 or any required legacy acceptance check fails.",
            "trigger_id": "RT-D-DEADLINE"
          },
          {
            "action": "Rollback the D canary to the preserved legacy state, pause migration, and assign the recovery owner before retrying.",
            "check": "Verify the named recovery owner at activation and time every recovery drill or recovery event.",
            "condition": "The recovery owner is absent or recovery exceeds the approved recovery-time objective.",
            "trigger_id": "RT-D-RECOVERY"
          }
        ]
      },
      {
        "gates": [
          {
            "check": "Run positive and negative admission tests against a B canary for cross-workspace mounts and credential scope.",
            "expected": "Only workspace-local mounts are admitted, cross-workspace mount attempts are rejected, and credentials authorize only the intended workspace.",
            "gate_id": "G-B-ISOLATION"
          },
          {
            "check": "Run separate warm and cold representative workloads on B and publish samples, sample counts, censoring, execution identity, and exclusions.",
            "expected": "Both separate distributions meet approved workload-specific SLOs and no pooled warm/cold inference is used.",
            "gate_id": "G-B-WORKLOAD"
          },
          {
            "check": "From a B canary, execute rollback to the preserved D bridge and run D compatibility and recovery checks.",
            "expected": "D is restored without data loss and all compatibility and recovery checks pass inside the approved recovery-time objective.",
            "gate_id": "G-B-ROLLBACK"
          }
        ],
        "option": "B",
        "owner": "Execution Fabric Operations",
        "phase": 2,
        "purpose": "Cut over to B as the bounded target supported by SEC-B-ISOLATION only after D bridge, ownership, workload, isolation, recovery, and rollback gates pass.",
        "rollback_triggers": [
          {
            "action": "Stop B traffic, revoke affected credentials, rollback to preserved D, and open a security incident before retrying.",
            "check": "Continuously evaluate mount admission and credential-scope audit events and rerun negative tests on policy changes.",
            "condition": "Any cross-workspace mount succeeds or any credential authorizes a workspace outside its intended scope.",
            "trigger_id": "RT-B-ISOLATION"
          },
          {
            "action": "Rollback the affected B canary to preserved D, retain the separate distributions, and reassess thresholds before expansion.",
            "check": "Evaluate warm and cold SLOs separately for every canary window and report censoring and invalid-run exclusions.",
            "condition": "Either workload-specific SLO fails, censoring exceeds its approved bound, or mixed workloads make the distribution invalid.",
            "trigger_id": "RT-B-SLO"
          }
        ]
      }
    ],
    "strategy": "Use D as a legacy-compatible, time-bounded migration bridge, then cut over to B only after ownership, isolation, rollback, recovery, and workload gates pass; keep A as a conditional warm-workload optimization and reject C's invalid pooled claim."
  },
